<?php
namespace App\Services;
use App\Collaboration\{CollaborationResourceReference,CollaborationResourceRegistry};use App\Models\{ResourceRevision,User};
final class ResourceAttributionService{public function __construct(private CollaborationResourceRegistry$resources,private ResourceAttributionRegistry$registry,private CollaborationIdentitySummary$identities){}public function forResource(User$viewer,string$type,int$id):array{$resource=$this->resources->resolve($viewer,new CollaborationResourceReference($type,$id),'view')->resource;$creatorId=$this->registry->creatorId($type,$resource);$creator=$creatorId?User::query()->select(['id','name','status'])->find($creatorId):null;$contributors=collect();if($this->registry->supportsContributors($type)){$latest=ResourceRevision::query()->where('resource_type',$type)->where('resource_id',$id)->where('revision_number','>',1)->whereNotNull('created_by')->selectRaw('created_by, MAX(created_at) as last_contributed_at')->groupBy('created_by')->orderByDesc('last_contributed_at')->get();$users=User::query()->whereIn('id',$latest->pluck('created_by'))->get(['id','name','status'])->keyBy('id');$contributors=$latest->map(function($row)use($users){$identity=$this->identities->fromUser($users->get($row->created_by));return$identity?$identity+['lastContributedAt'=>$row->last_contributed_at]:null;})->filter()->values();}return['resourceType'=>$type,'resourceId'=>(string)$id,'creator'=>$this->identities->fromUser($creator),'contributors'=>$contributors,'contributorSemantics'=>'meaningful_configuration_revision_authors'];}}